import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def _shift(worker: str, day: str, start: int, end: int) -> Shift:
    return Shift(worker, day, Span(start, end))


class TimesheetLineTests(unittest.TestCase):
    def test_busiest_workers_first(self):
        shifts = [
            _shift("Odell", "mon", 540, 720),
            _shift("Brisa", "mon", 540, 1020),
            _shift("Brisa", "tue", 540, 630),
            _shift("Quill", "wed", 480, 870),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 9.5 hours",
                "Quill: 1 shifts, 6.5 hours",
                "Odell: 1 shifts, 3.0 hours",
            ]
        )

    def test_equal_hours_sorted_by_name(self):
        shifts = [_shift("Quill", "mon", 540, 600), _shift("Brisa", "tue", 540, 600)]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Brisa: 1 shifts, 1.0 hours", "Quill: 1 shifts, 1.0 hours"]
        )

    def test_overlapping_shifts_both_count(self):
        shifts = [_shift("Brisa", "mon", 540, 720), _shift("Brisa", "mon", 600, 780)]
        self.assertEqual(timesheet_lines(shifts), ["Brisa: 2 shifts, 6.0 hours"])

    def test_hours_rounded_to_one_decimal(self):
        shifts = [_shift("Brisa", "mon", 540, 580)]
        self.assertEqual(timesheet_lines(shifts), ["Brisa: 1 shifts, 0.7 hours"])

    def test_no_shifts_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_empty_worker_name_raises(self):
        shifts = [_shift("Brisa", "mon", 540, 600), _shift("", "tue", 540, 600)]
        with self.assertRaises(ValueError):
            timesheet_lines(shifts)

    def test_blank_worker_name_raises(self):
        shifts = [_shift("Brisa", "mon", 540, 600), _shift("   ", "tue", 540, 600)]
        with self.assertRaises(ValueError):
            timesheet_lines(shifts)
